tokens:
--scheme: light;
color-scheme: light;
--bg: #eef0e4;
--bg2: #e6e9da;
--surface: #fbfcf5;
--surface2: #e2e6d4;
--ink: #14271f;
--muted: #2f4639;
--faint: #4a5f53;
--cardmeta: #1f3329;
--gold: #1f5e43;
--gold-soft: #174a35;
--gold-deep: #14271f;
--on-gold: #ffffff;
--ink-soft: #2f4639;
--line: rgba(20, 39, 31, 0.18);
--line-strong: #1f5e43;
--ok: #1f6b33;
--warn: #7f5800;
--bad: #b0220f;
--shadow: 0 1px 1px rgba(20, 45, 32, 0.14), 0 6px 0 -2px rgba(20, 45, 32, 0.10), 0 10px 18px rgba(20, 45, 32, 0.10);
--elev-1: 0 1px 1px rgba(20, 45, 32, 0.14), 0 3px 6px rgba(20, 45, 32, 0.10);
--elev-2: 0 2px 2px rgba(20, 45, 32, 0.14), 0 10px 22px rgba(20, 45, 32, 0.14);
--elev-3: 0 4px 6px rgba(20, 45, 32, 0.16), 0 24px 60px rgba(20, 45, 32, 0.22);
--scrim: rgba(20, 39, 31, 0.42);
--focus: #2f6fd6;
--th-bg: #e2e6d4;
--tabgrad1: #e2e6d4; --tabgrad2: #fbfcf5;
--toastgrad1: #e2e6d4; --toastgrad2: #fbfcf5;
--foot-bg: rgba(238, 240, 228, 0.95);
--drawerbar-bg: rgba(251, 252, 245, 0.96);
--ph-bg: #e2e6d4;
--sel-bg: rgba(31, 94, 67, 0.15);
--row-hover: rgba(31, 94, 67, 0.07);
--hold-bg: linear-gradient(135deg, #e2e6d4, #fbfcf5);
--skeleton1: #e2e6d4; --skeleton2: #eef0e4;
--grain-op: 0.035;
--wing-dur: 0.42s;
--wing-rise: 14px;
/* legacy aliases resolved on <html> */
--text: var(--ink); --panel: var(--surface); --chip: var(--surface2); --missing: var(--faint);
--border: var(--line); --gold-dim: var(--gold-deep); --danger: var(--bad);
--serif: "Fraunces", Georgia, "Times New Roman", serif;
--radius: 4px;
/* the note treatment (styles/style-layer.css, ui "note"): engraved double rules and the seal red */
--note-rule: rgba(20, 39, 31, 0.55);
--note-seal: #a8321d;
/* the dark display-case interior used by the instrument panels (styles/style-layer.css, ui "paper"): intaglio green */
--case-bg: #12261d;
--case-bg2: #163024;
--case-surface: #1b382b;
--case-surface2: #234536;
--case-ink: #ffffff;
--case-muted: #d9e6dc;
--case-faint: #b5c9bb;
--case-gold: #e9c98a;
--case-gold-soft: #f5deb0;
--case-on-gold: #12261d;
/* the page palette again, for paper labels inside a case */
--paper-bg: #eef0e4;
--paper-bg2: #e6e9da;
--paper-surface: #fbfcf5;
--paper-surface2: #e2e6d4;
--paper-ink: #14271f;
--paper-muted: #2f4639;
--paper-faint: #4a5f53;
--paper-gold: #1f5e43;
--paper-gold-soft: #174a35;
--paper-on-gold: #ffffff;

